import React, { useState, useEffect } from 'react';
import {
  Card,
  CardContent,
  Typography,
  Grid,
  Button,
  Box,
  Chip,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormGroup,
  FormControlLabel,
  Checkbox,
  CircularProgress,
  Alert,
  Divider,
  LinearProgress
} from '@mui/material';
import {
  Store,
  LocationOn as MapPin,
  Business as Building,
  BarChart,
  TrendingUp,
  Inventory as Package,
  FlashOn as Zap,
  CheckCircle,
  Warning as AlertCircle
} from '@mui/icons-material';

interface StoreData {
  location: string;
  city: string;
  total_walls: number;
  lob_breakdown: Record<string, string>;
  capacity_summary: Record<string, number>;
}

interface LOBRecommendation {
  priority_score: number;
  current_walls: number;
  current_capacity: number;
  target_allocation: number;
  recommendation: string;
}

interface StoreRecommendations {
  optimization: {
    current_distribution: Record<string, number>;
    optimal_distribution: Record<string, number>;
    changes_needed: Record<string, any>;
  };
  lob_priorities: Record<string, LOBRecommendation>;
  summary: string;
}

interface GenerationResult {
  store_name: string;
  generation_mode: string;
  total_planograms: number;
  lob_categories: string[];
  planograms: Record<string, string[]>;
}

const StoreSelector: React.FC = () => {
  const [storeAnalysis, setStoreAnalysis] = useState<any>(null);
  const [selectedStore, setSelectedStore] = useState<string>('');
  const [storeDetails, setStoreDetails] = useState<StoreData | null>(null);
  const [recommendations, setRecommendations] = useState<StoreRecommendations | null>(null);
  const [loading, setLoading] = useState(false);
  const [generationMode, setGenerationMode] = useState<'LOB_WISE' | 'PRODUCT_WISE' | 'FULL_STORE'>('LOB_WISE');
  const [selectedLOBs, setSelectedLOBs] = useState<string[]>([]);
  const [generating, setGenerating] = useState(false);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);

  useEffect(() => {
    fetchStoreAnalysis();
  }, []);

  useEffect(() => {
    if (selectedStore) {
      fetchStoreDetails();
      fetchRecommendations();
    }
  }, [selectedStore]);

  const fetchStoreAnalysis = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/stores/analysis');
      const data = await response.json();

      if (data.success) {
        setStoreAnalysis(data.data);
      }
    } catch (error) {
      console.error('Error fetching store analysis:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchStoreDetails = async () => {
    if (!selectedStore) return;

    try {
      const response = await fetch(`/api/stores/${encodeURIComponent(selectedStore)}/lob-details`);
      const data = await response.json();

      if (data.success) {
        setStoreDetails(data.data);
      }
    } catch (error) {
      console.error('Error fetching store details:', error);
    }
  };

  const fetchRecommendations = async () => {
    if (!selectedStore) return;

    try {
      const response = await fetch(`/api/stores/${encodeURIComponent(selectedStore)}/recommendations`);
      const data = await response.json();

      if (data.success) {
        setRecommendations(data.data);
      }
    } catch (error) {
      console.error('Error fetching recommendations:', error);
    }
  };

  const generatePlanograms = async () => {
    if (!selectedStore) return;

    try {
      setGenerating(true);
      const response = await fetch(`/api/stores/${encodeURIComponent(selectedStore)}/generate-planograms`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          mode: generationMode,
          selected_lobs: generationMode === 'PRODUCT_WISE' ? selectedLOBs : undefined
        })
      });

      const data = await response.json();

      if (data.success) {
        // Poll for job completion
        pollJobStatus(data.job_id);
      }
    } catch (error) {
      console.error('Error generating planograms:', error);
      setGenerating(false);
    }
  };

  const pollJobStatus = async (jobId: string) => {
    const interval = setInterval(async () => {
      try {
        const response = await fetch(`/api/jobs/${jobId}`);
        const data = await response.json();

        if (data.success && data.job) {
          if (data.job.status === 'completed') {
            setGenerationResult(data.job.result);
            setGenerating(false);
            clearInterval(interval);
          } else if (data.job.status === 'failed') {
            console.error('Job failed:', data.job.error);
            setGenerating(false);
            clearInterval(interval);
          }
        }
      } catch (error) {
        console.error('Error polling job status:', error);
        setGenerating(false);
        clearInterval(interval);
      }
    }, 2000);
  };

  const getStoreOptions = () => {
    if (!storeAnalysis?.store_selector) return [];
    return Object.keys(storeAnalysis.store_selector);
  };

  const getLOBOptions = () => {
    if (!storeDetails?.wall_details) return [];
    return Object.keys(storeDetails.wall_details).filter(lob => 
      lob !== 'audio' && storeDetails.wall_details[lob]?.wall_count > 0
    );
  };

  const formatLOBName = (lob: string) => {
    return lob.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  const getRecommendationColor = (recommendation: string) => {
    switch (recommendation) {
      case 'EXPAND_RECOMMENDED': return 'bg-green-100 text-green-800';
      case 'CONSIDER_REDUCING': return 'bg-red-100 text-red-800';
      case 'AT_CAPACITY': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-blue-100 text-blue-800';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin" />
        <span className="ml-2">Loading store analysis...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center space-x-2">
        <Store className="h-6 w-6" />
        <h1 className="text-2xl font-bold">Store LOB Distribution Analyzer</h1>
      </div>

      {/* Store Selection */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <MapPin className="h-5 w-5" />
            <span>Store Selection</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <select
              value={selectedStore}
              onChange={(e) => setSelectedStore(e.target.value)}
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="">Select a store...</option>
              {getStoreOptions().map(store => (
                <option key={store} value={store}>
                  {store} ({storeAnalysis.store_selector[store]?.city})
                </option>
              ))}
            </select>

            {selectedStore && storeDetails && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-4">
                <div className="flex items-center space-x-2">
                  <Building className="h-4 w-4 text-gray-500" />
                  <span className="text-sm text-gray-600">Location:</span>
                  <span className="font-medium">{storeDetails.location}</span>
                </div>
                <div className="flex items-center space-x-2">
                  <MapPin className="h-4 w-4 text-gray-500" />
                  <span className="text-sm text-gray-600">City:</span>
                  <span className="font-medium">{storeDetails.city}</span>
                </div>
                <div className="flex items-center space-x-2">
                  <Package className="h-4 w-4 text-gray-500" />
                  <span className="text-sm text-gray-600">Total Walls:</span>
                  <span className="font-medium">{storeDetails.total_walls}</span>
                </div>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* LOB Breakdown */}
      {selectedStore && storeDetails && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <BarChart3 className="h-5 w-5" />
              <span>Current LOB Breakdown</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
              {Object.entries(storeDetails.wall_details).map(([lob, details]) => {
                if (details.wall_count === 0) return null;
                return (
                  <div key={lob} className="p-3 border border-gray-200 rounded-lg">
                    <div className="flex justify-between items-center">
                      <span className="font-medium text-sm">{formatLOBName(lob)}</span>
                      <Badge variant="secondary">{details.wall_count} walls</Badge>
                    </div>
                    <div className="text-xs text-gray-500 mt-1">
                      Capacity: {details.total_capacity}
                    </div>
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Recommendations */}
      {recommendations && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <TrendingUp className="h-5 w-5" />
              <span>Optimization Recommendations</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg">
                <p className="text-sm text-blue-800">{recommendations.summary}</p>
              </div>

              {recommendations.optimization?.changes_needed && Object.keys(recommendations.optimization.changes_needed).length > 0 && (
                <div className="space-y-2">
                  <h4 className="font-medium">Recommended Changes:</h4>
                  <div className="space-y-2">
                    {Object.entries(recommendations.optimization.changes_needed).map(([lob, change]: [string, any]) => (
                      <div key={lob} className="flex items-center justify-between p-2 border border-gray-200 rounded">
                        <span className="text-sm font-medium">{formatLOBName(lob)}</span>
                        <div className="flex items-center space-x-2">
                          <Badge className={change.action === 'ADD' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}>
                            {change.action} {change.walls_affected} wall(s)
                          </Badge>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Planogram Generation */}
      {selectedStore && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <Zap className="h-5 w-5" />
              <span>Generate Planograms</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Generation Mode:</label>
                <select
                  value={generationMode}
                  onChange={(e) => setGenerationMode(e.target.value as any)}
                  className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500"
                >
                  <option value="LOB_WISE">Generate all LOB categories</option>
                  <option value="PRODUCT_WISE">Generate specific categories</option>
                  <option value="FULL_STORE">Full store optimization</option>
                </select>
              </div>

              {generationMode === 'PRODUCT_WISE' && (
                <div>
                  <label className="block text-sm font-medium mb-2">Select LOB Categories:</label>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {getLOBOptions().map(lob => (
                      <label key={lob} className="flex items-center space-x-2">
                        <input
                          type="checkbox"
                          checked={selectedLOBs.includes(lob)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedLOBs([...selectedLOBs, lob]);
                            } else {
                              setSelectedLOBs(selectedLOBs.filter(l => l !== lob));
                            }
                          }}
                          className="rounded border-gray-300"
                        />
                        <span className="text-sm">{formatLOBName(lob)}</span>
                      </label>
                    ))}
                  </div>
                </div>
              )}

              <Button
                onClick={generatePlanograms}
                disabled={generating || (generationMode === 'PRODUCT_WISE' && selectedLOBs.length === 0)}
                className="w-full"
              >
                {generating ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin mr-2" />
                    Generating Planograms...
                  </>
                ) : (
                  <>
                    <Zap className="h-4 w-4 mr-2" />
                    Generate Planograms
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Generation Results */}
      {generationResult && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <CheckCircle className="h-5 w-5 text-green-600" />
              <span>Generation Complete</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="text-center p-3 border border-gray-200 rounded-lg">
                  <div className="text-2xl font-bold text-blue-600">{generationResult.total_planograms}</div>
                  <div className="text-sm text-gray-600">Total Planograms</div>
                </div>
                <div className="text-center p-3 border border-gray-200 rounded-lg">
                  <div className="text-2xl font-bold text-green-600">{generationResult.lob_categories.length}</div>
                  <div className="text-sm text-gray-600">LOB Categories</div>
                </div>
                <div className="text-center p-3 border border-gray-200 rounded-lg">
                  <div className="text-2xl font-bold text-purple-600">{generationResult.generation_mode}</div>
                  <div className="text-sm text-gray-600">Generation Mode</div>
                </div>
              </div>

              <div className="space-y-2">
                <h4 className="font-medium">Generated Categories:</h4>
                {generationResult.lob_categories.map(category => (
                  <div key={category} className="flex justify-between items-center p-2 border border-gray-200 rounded">
                    <span className="font-medium">{formatLOBName(category)}</span>
                    <Badge variant="outline">
                      {generationResult.planograms[category]?.length || 0} planograms
                    </Badge>
                  </div>
                ))}
              </div>

              <div className="space-y-2">
                <h4 className="font-medium">Generated Files:</h4>
                <div className="max-h-40 overflow-y-auto space-y-1">
                  {Object.entries(generationResult.planograms).map(([category, files]) => (
                    <div key={category} className="space-y-1">
                      <div className="font-medium text-sm text-gray-700">{formatLOBName(category)}:</div>
                      {files.map((file, index) => (
                        <div key={index} className="text-xs font-mono bg-gray-100 p-1 rounded">
                          {file}
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default StoreSelector;
